SELECT json_object('obs','bytes','declined',CASE WHEN (SELECT payload FROM source_blob WHERE doc_id=1) IS NULL THEN 1 ELSE 0 END,'value_kind','bytes','value_hex',(SELECT hex(substr(payload,1,64)) FROM source_blob WHERE doc_id=1),'coord',NULL,'provenance',NULL,'exact',json_object('length',(SELECT source_len FROM documents WHERE doc_id=1),'sha256',(SELECT source_sha256 FROM documents WHERE doc_id=1)),'revision',NULL)